// N+1 演示：操作计数（1+N 次查询 vs 一次 JOIN），结果集必须一致
const authors = [];
for (let i = 1; i <= 5; i++) authors.push({ id: i, name: 'author' + i });

const posts = [];
let pid = 0;
for (const a of authors) {
  const n = (a.id % 3) + 1;
  for (let i = 0; i < n; i++) { pid += 1; posts.push({ id: pid, authorId: a.id, title: 'post' + pid }); }
}

let ops = 0;

function query(op) { ops += 1; return op(); }
const findAllAuthors = () => query(() => authors.slice());
const findPostsByAuthor = (id) => query(() => posts.filter(p => p.authorId === id));
const findAuthorsWithPosts = () => query(() =>
  authors.map(a => ({ author: a, posts: posts.filter(p => p.authorId === a.id) })));

function nested() {
  return findAllAuthors().map(a => ({
    name: a.name,
    posts: findPostsByAuthor(a.id).map(p => p.title),
  }));
}

function joined() {
  return findAuthorsWithPosts().map(r => ({
    name: r.author.name,
    posts: r.posts.map(p => p.title),
  }));
}

ops = 0;
const rNested = nested();
const opsNested = ops;

ops = 0;
const rJoined = joined();
const opsJoined = ops;

console.log('authors=' + authors.length + ' posts=' + posts.length);
console.log('nested_queries=' + opsNested + ' joined_queries=' + opsJoined);
console.log('nested_is_1_plus_N=' + (opsNested === authors.length + 1));
console.log('joined_is_single_query=' + (opsJoined === 1));
console.log('same_result=' + (JSON.stringify(rNested) === JSON.stringify(rJoined)));
console.log('rows_returned=' + posts.length);
console.log('nested_sample=' + JSON.stringify(rNested[0]));
console.log('query_reduction_ratio_int=' + Math.round(opsNested / opsJoined));
